const token=prompt('Enter the admin token'),auth={Authorization:'Bearer '+token,'Content-Type':'application/json'},$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function req(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:auth,body:body?JSON.stringify(body):undefined}),d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
const controls=(kind,id,name,extra='')=>`<div class="tree-actions">${extra}<button class="icon move" data-kind="${kind}" data-id="${id}" data-dir="up" title="Move up">↑</button><button class="icon move" data-kind="${kind}" data-id="${id}" data-dir="down" title="Move down">↓</button><input class="rename" value="${esc(name)}"><button class="icon save-name" data-kind="${kind}" data-id="${id}" title="Save name">✓</button><button class="icon danger remove" data-kind="${kind}" data-id="${id}" title="Remove">×</button></div>`;
function branch(title,body,actions=''){return `<section class="tree-node"><div class="tree-line"><button class="tree-toggle">∨</button><strong>${title}</strong>${actions}</div><div class="tree-children">${body}</div></section>`}
async function render(){try{const d=await req('/api/admin/status'),paused=d.meta.feed_paused==='true';$('#app-version').textContent='Version '+d.version;$('#export-dir').value='RACE_EXPORT_DIR='+d.sourceConfig.hostDirectory;$('#export-filename').value='RACE_EXPORT_FILENAME='+d.sourceConfig.filename;$('#file-status').textContent=d.file.exists?`Reading ${d.file.configured} · ${d.file.bytes} bytes`:`Waiting for ${d.file.configured}`;$('#import-status').textContent=d.meta.last_error?'Last error: '+d.meta.last_error:'Last successful import: '+(d.meta.last_import||'waiting');$('#event-status').value=d.meta.status||d.status||'Live';$('#feed-toggle').textContent=paused?'Start live updates':'Stop live updates';let html=`<div class="tree-create"><input id="new-tournament" placeholder="New tournament"><button class="btn create-tournament">Add tournament</button></div>`;
html+=d.tournaments.map(t=>{const levels=d.levels.filter(l=>l.tournament_id===t.id);const levelHtml=levels.map(l=>{const races=d.races.filter(r=>r.level_id===l.id);const raceHtml=races.map(r=>{const events=d.events.filter(e=>e.tournament===t.name&&e.level===l.name&&e.stage===r.name);return branch(esc(r.name),events.map(e=>`<div class="tree-leaf">${esc(e.name)} <button class="visibility" data-id="${esc(e.id)}">${e.visible?'Visible':'Hidden'}</button></div>`).join('')||'<div class="empty-tree">No RaceTec race assigned</div>',controls('races',r.id,r.name,`<button class="lap-toggle" data-r="${r.id}">Fastest lap: ${r.fastest_lap?'On':'Off'}</button>`))}).join('');return branch(esc(l.name),raceHtml+`<div class="tree-create compact"><input placeholder="New race"><button class="btn create-race" data-t="${t.id}" data-l="${l.id}">Add race</button></div>`,controls('levels',l.id,l.name))}).join('');return branch(esc(t.name),levelHtml+`<div class="tree-create compact"><input placeholder="New round"><button class="btn create-level" data-t="${t.id}">Add round</button></div>`,controls('tournaments',t.id,t.name))}).join('');const unassigned=d.events.filter(e=>!d.tournaments.some(t=>t.name===e.tournament)&&e.name);html+=branch('Unassigned RaceTec races',unassigned.map(e=>`<div class="unassigned-race"><span>${esc(e.name)}</span><select data-event="${esc(e.id)}"><option value="">Choose destination…</option>${d.races.map(r=>{const l=d.levels.find(x=>x.id===r.level_id),t=d.tournaments.find(x=>x.id===r.tournament_id);return l&&t?`<option value="${r.id}">${esc(t.name)} → ${esc(l.name)} → ${esc(r.name)}</option>`:''}).join('')}</select><button class="btn assign" data-event="${esc(e.id)}">Assign</button></div>`).join('')||'<div class="empty-tree">Everything is assigned.</div>');$('#event-list').innerHTML=html;wire(d)}catch(e){$('#event-list').textContent=e.message}}
function wire(d){$('#feed-toggle').onclick=async()=>{await req('/api/admin/feed',{running:d.meta.feed_paused==='true'});render()};$('#event-status').onchange=async e=>{await req('/api/admin/status',{status:e.target.value});render()};$('#event-list').onclick=async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.classList.contains('tree-toggle')){const c=b.closest('.tree-node').querySelector(':scope > .tree-children');c.hidden=!c.hidden;b.textContent=c.hidden?'›':'∨'}else if(b.classList.contains('move')){await req('/api/admin/'+b.dataset.kind+'/'+b.dataset.id+'/move',{direction:b.dataset.dir});render()}else if(b.classList.contains('save-name')){const input=b.parentElement.querySelector('.rename'),name=input.value.trim();if(name){await req('/api/admin/'+b.dataset.kind+'/'+b.dataset.id,{name});render()}}else if(b.classList.contains('remove')){if(confirm('Remove this item and unassign its races?')){await req('/api/admin/'+b.dataset.kind+'/'+b.dataset.id,{delete:true});render()}}else if(b.classList.contains('create-tournament')){const name=$('#new-tournament').value.trim();if(name){await req('/api/admin/tournaments',{name});render()}}else if(b.classList.contains('create-level')){const name=b.parentElement.querySelector('input').value.trim();if(name){await req('/api/admin/levels',{tournamentId:+b.dataset.t,name});render()}}else if(b.classList.contains('create-race')){const name=b.parentElement.querySelector('input').value.trim();if(name){await req('/api/admin/races',{tournamentId:+b.dataset.t,levelId:+b.dataset.l,name});render()}}else if(b.classList.contains('lap-toggle')){const r=d.races.find(x=>x.id===+b.dataset.r);await req('/api/admin/races/'+r.id+'/fastest-lap',{enabled:!r.fastest_lap});render()}else if(b.classList.contains('assign')){const row=b.closest('.unassigned-race'),race=d.races.find(x=>x.id===+row.querySelector('select').value),event=d.events.find(x=>x.id===b.dataset.event);if(!race||!event)return;const level=d.levels.find(x=>x.id===race.level_id),tournament=d.tournaments.find(x=>x.id===race.tournament_id);await req('/api/admin/assignments',{assignments:[{eventId:event.id,tournament:tournament.name,level:level.name,race:race.name,raceId:race.id,name:event.name}]});render()}else if(b.classList.contains('visibility')){await req('/api/admin/events/'+encodeURIComponent(b.dataset.id),{visible:b.textContent==='Hidden'});render()}}catch(err){alert(err.message)}}}
render();